CREATE TABLE Clientes (idcliente INT, nombre VARCHAR (100), perfilbio TEXT, fecharegistro DATE) -- INT porque la identificación del cliente es numérica y entera - VARCHAR 100 para nombre, limitando la memoria a utilizar de manera innecesaria -  TEXT para perfil_bio ya que no tengo referencia de cuánto podría extenderse el cliente escribiendo - DATE para fecha de registro. Así será posible calcular datos cronológicos en un futuro.
CREATE TABLE Productos (idproducto INT, descripcion VARCHAR(255) , precio DECIMAL, estaactivo INT ) --INT:es un identificador numérico - VARCHAR(255) porque tengo información sobre el límite de carácteres, entonces usamos la funcion para no gastar memoria demás como si estaría usando TEXT. - DECIMAL para el Precio porque trabaja con números decimales exactos - INT para la saber si existe o no, suponiendo que se use un 0 para decir NO, y el 1 para SI.
